pub fn from_fn<F>(len: usize, mut f: F) -> Self where F: FnMut(usize) -> bool {
    let mut bit_vec = BitVec::with_capacity(len);
    for i in 0..len {
        bit_vec.push(f(i));
    }
    bit_vec.nbits = len;
    bit_vec
}

